"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useEffect, useState } from "react";
import { ArrowUpRight, Copy, X } from "react-feather";
import { Button, Flex, SpinningLoader, Text, styled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const CloseIcon = styled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const SummaryCard = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  width: "100%",
  marginBottom: "$spacing24"
});
const UsdPill = styled(Flex, {
  backgroundColor: "$surface3",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$rounded12",
  justifyContent: "center",
  alignItems: "center",
  marginLeft: "$spacing8"
});
const PermitSection = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  marginBottom: "$spacing24"
});
const DoneButton = styled(Button, {
  width: "100%",
  marginTop: "$spacing24",
  py: "$spacing24"
});
const AddressPill = styled(Flex, {
  backgroundColor: "$surface2",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$rounded12",
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap4",
  marginLeft: "$spacing8"
});
const ProgressRow = styled(Flex, {
  flexDirection: "row",
  width: "100%",
  gap: "$gap8",
  marginBottom: "$spacing12"
});
const ProgressSegment = styled(Flex, {
  height: "4px",
  borderRadius: "$roundedFull",
  flex: 1,
  variants: {
    status: {
      active: { backgroundColor: "$accent1" },
      // Blue
      completed: { backgroundColor: "$greenVibrant" },
      // Green (assuming variable exists, else use hex or fallback)
      pending: { backgroundColor: "$surface3" }
      // Gray
    }
  }
});
const FooterRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const ExplorerLink = styled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap4",
  cursor: "pointer"
});
export default function ConfirmModal({ isOpen, onClose, vault, amount, type }) {
  const colors = useSporeColors();
  const [step, setStep] = useState(1);
  const tokenSymbol = vault.token.symbol;
  const isDeposit = type === "deposit";
  const actionLabel = isDeposit ? "Deposit" : "Withdraw";
  const parsedAmount = parseFloat(amount || "0");
  const usdValue = parsedAmount;
  useEffect(() => {
    if (isOpen) {
      if (step === 1) {
        const timer = setTimeout(() => setStep(2), 3e3);
        return () => clearTimeout(timer);
      } else if (step === 2) {
        const timer = setTimeout(() => setStep(3), 3e3);
        return () => clearTimeout(timer);
      }
    } else {
      setStep(1);
    }
  }, [isOpen, step]);
  const stepText = step === 1 ? "Enable permit2 contract" : "Execute your bundle";
  const addressText = step === 1 ? "0xb98c...746A" : "0x6BFd...20C4";
  const showProgress = step < 3;
  return <Modal
    name={"ConfirmModal"}
    isModalOpen={isOpen}
    onClose={onClose}
    backgroundColor={colors.surface1.val}
    maxWidth={480}
    padding="$spacing24"
  >
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          Confirm
        </Text>
        <CloseIcon onPress={onClose}>
          <X size={24} color={colors.neutral2.val} />
        </CloseIcon>
      </ModalHeader>

      <SummaryCard>
        {
    /* Vault Header inside Card */
  }
        <Flex flexDirection="row" alignItems="center" gap="$gap12" mb="$spacing24">
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name ?? ""}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
          <Text variant="heading3" color="$neutral1">
            {vault.name}
          </Text>
        </Flex>

        {
    /* Amount Section */
  }
        <Text variant="body2" color="$neutral2" mb="$spacing8">
          {actionLabel}
        </Text>

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Flex flexDirection="row" alignItems="center">
            <Text variant="heading2" color="$neutral1">
              {amount || "0"}
            </Text>
            <Text variant="heading2" color="$neutral2" ml="$spacing4">
              {tokenSymbol}
            </Text>
            <UsdPill>
              <Text variant="body3" color="$neutral2">
                $&#60; {usdValue.toFixed(2)}
              </Text>
            </UsdPill>
          </Flex>
          {
    /* Icon on right */
  }
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name ?? ""}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
        </Flex>
      </SummaryCard>

      {showProgress ? <>
          <PermitSection>
            <Flex flexDirection="row" alignItems="center">
              <Text variant="body2" color="$neutral1">
                {stepText}
              </Text>
              <AddressPill>
                <Text variant="body4" color="$neutral2">
                  {addressText}
                </Text>
                <ArrowUpRight size={12} color={colors.neutral2.val} />
              </AddressPill>
            </Flex>
            {
    /* Status Circle / Spinner */
  }
            <SpinningLoader size={20} color={colors.accent1.val} />
          </PermitSection>

          <ProgressRow>
            {
    /* Segment 1: Active in step 1, Completed (Green) in step 2 */
  }
            <ProgressSegment
    status={step === 1 ? "active" : "completed"}
    style={step === 2 ? { backgroundColor: "#48C28D" } : {}}
  />{" "}
            {
    /* Hardcoded green for safety if var missing */
  }
            {
    /* Segment 2: Pending in step 1, Active in step 2 */
  }
            <ProgressSegment status={step === 1 ? "pending" : "active"} />
          </ProgressRow>
        </> : <DoneButton>Done</DoneButton>}

      <FooterRow>
        {step < 3 ? <Text variant="body3" color="$neutral2">
            Signature {step} / 2 - Proceed in your wallet
          </Text> : <Flex flexDirection="row" alignItems="center" gap="$gap4" flex={1} mt={"$spacing12"}>
            {
    /* <Text variant="body3" color="$neutral2" >
      Transaction
    </Text>
    <Text variant="body3" color="$neutral2" style={{ textDecoration: 'underline' }}>
      0x74a7...efff
    </Text>
    <Text variant="body3" color="$neutral2">
      is sent to your smart wallet!
    </Text> */
  }
          </Flex>}

        {step >= 2 && <ExplorerLink>
            {step < 3 && <Copy size={14} color={colors.neutral2.val} />}
            {step === 3 && <Copy size={14} color={colors.neutral2.val} style={{ marginRight: 8 }} />}
            <Text variant="body3" color="$neutral2" ml={step < 3 ? "$spacing4" : "$0"}>
              View on explorer
            </Text>
            <ArrowUpRight size={14} color={colors.neutral2.val} />
          </ExplorerLink>}
      </FooterRow>
    </Modal>;
}
