"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { ArrowRight, X } from "react-feather";
import { Button, Flex, Text, styled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const CloseIcon = styled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const ReviewCard = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  width: "100%"
});
const InfoRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing12"
});
const SubmitButton = styled(Button, {
  width: "100%",
  marginTop: "$spacing24",
  py: "$spacing24"
});
const DisclaimerText = styled(Text, {
  variant: "body4",
  color: "$neutral2",
  marginTop: "$spacing24",
  lineHeight: "20px"
});
const UsdPill = styled(Flex, {
  backgroundColor: "$surface3",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$rounded12",
  justifyContent: "center",
  alignItems: "center"
});
export default function ReviewModal({ isOpen, onClose, onConfirm, vault, amount, type }) {
  const colors = useSporeColors();
  const tokenSymbol = vault.token.symbol;
  const isDeposit = type === "deposit";
  const title = isDeposit ? "Review" : "Review";
  const actionLabel = isDeposit ? "Deposit" : "Withdraw";
  const parsedAmount = parseFloat(amount || "0");
  const usdValue = parsedAmount;
  const currentPosition = 0;
  const newPosition = isDeposit ? currentPosition + parsedAmount : Math.max(0, currentPosition - parsedAmount);
  return <Modal
    name={"ReviewModal"}
    isModalOpen={isOpen}
    onClose={onClose}
    backgroundColor={colors.surface1.val}
    maxWidth={480}
    padding="$spacing24"
  >
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          {title}
        </Text>
        <CloseIcon onPress={onClose}>
          <X size={24} color={colors.neutral2.val} />
        </CloseIcon>
      </ModalHeader>

      <ReviewCard>
        {
    /* Vault Header inside Card */
  }
        <Flex flexDirection="row" alignItems="center" gap="$gap12" mb="$spacing24">
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name ?? ""}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
          <Text variant="heading3" color="$neutral1">
            {vault.name}
          </Text>
        </Flex>

        {
    /* Amount Section */
  }
        <Text variant="body2" color="$neutral2" mb="$spacing8">
          {actionLabel}
        </Text>

        <Flex
    flexDirection="row"
    justifyContent="space-between"
    alignItems="center"
    mb="$spacing16"
    pb="$spacing16"
    style={{ borderBottom: `1px solid ${colors.surface3.val}` }}
  >
          <Flex flexDirection="row" alignItems="baseline" gap="$gap8">
            <Text variant="heading2" color="$neutral1">
              {amount || "0"}
            </Text>
            <Text variant="heading2" color="$neutral2">
              {tokenSymbol}
            </Text>
          </Flex>
          <UsdPill>
            <Text variant="body3" color="$neutral2">
              ${usdValue.toFixed(2)}
            </Text>
          </UsdPill>
          {
    /* Icon on right */
  }
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name ?? ""}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
        </Flex>

        {
    /* Stats */
  }
        <InfoRow>
          <Text variant="body2" color="$neutral2">
            {actionLabel} ({tokenSymbol})
          </Text>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body2" color="$neutral2">
              {currentPosition < 0.01 ? "< 0.01" : currentPosition.toFixed(2)}
            </Text>
            <ArrowRight size={14} color={colors.neutral2.val} />
            <Text variant="body2" color="$neutral1">
              {newPosition.toFixed(2)}
            </Text>
          </Flex>
        </InfoRow>

        <InfoRow>
          <Text variant="body2" color="$neutral2">
            APY
          </Text>
          <Flex flexDirection="row" gap="$gap4">
            <Text variant="body2" color="$neutral1">
              {vault.apy.toFixed(2)}%
            </Text>
            <Text variant="body2" color="$accent1">
              ✦
            </Text>
          </Flex>
        </InfoRow>

        <InfoRow style={{ marginBottom: 0 }}>
          <Text variant="body2" color="$neutral2">
            Exposure
          </Text>
          <Flex flexDirection="row" gap="-8px">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol="WBTC"
    tokenName="WBTC"
    images={[]}
    size={20}
  />
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol="WETH"
    tokenName="WETH"
    images={[]}
    size={20}
  />
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol="USDC"
    tokenName="USDC"
    images={[]}
    size={20}
  />
          </Flex>
        </InfoRow>
      </ReviewCard>

      <DisclaimerText>
        By confirming this transaction, you agree to the{" "}
        <Text variant="body4" style={{ textDecoration: "underline" }}>
          Terms of Use
        </Text>{" "}
        and the services provisions relating to the Morpho Vault.
      </DisclaimerText>

      <SubmitButton size="large" emphasis="primary" onPress={onConfirm}>
        Confirm
      </SubmitButton>
    </Modal>;
}
